#include <condition_variable>
#include <cstddef>
#include <deque>
#include <mutex>
#include <optional>

template <typename T>
class WorkQueue
{
public:
    bool push(T item)
    {
        {
            std::lock_guard<std::mutex> lock{ m_mutex };
            if (m_closed) return false;
            m_items.push_back(std::move(item));
        }
        m_ready.notify_one();                   // notify after unlocking, so the woken thread can take the lock
        return true;
    }

    std::optional<T> pop()
    {
        std::unique_lock<std::mutex> lock{ m_mutex };
        m_ready.wait(lock, [&] { return !m_items.empty() || m_closed; });
        return takeLocked();
    }

    std::optional<T> tryPop()
    {
        std::lock_guard<std::mutex> lock{ m_mutex };
        return takeLocked();
    }

    void close()
    {
        {
            std::lock_guard<std::mutex> lock{ m_mutex };
            m_closed = true;
        }
        m_ready.notify_all();
    }

    std::size_t size() const
    {
        std::lock_guard<std::mutex> lock{ m_mutex };
        return m_items.size();
    }

private:
    std::optional<T> takeLocked()
    {
        if (m_items.empty()) return std::nullopt;
        T item{ std::move(m_items.front()) };
        m_items.pop_front();
        return item;
    }

    mutable std::mutex m_mutex;
    std::condition_variable m_ready;
    std::deque<T> m_items;
    bool m_closed{ false };
};

hints:
A `std::condition_variable` (in `<condition_variable>`) lets one thread sleep until another says something changed. The waiting side needs a `std::unique_lock` (a lock that `wait` can release while it sleeps); the other side changes the data under the mutex, then calls `notify_one()` (wake one waiter) or `notify_all()` (wake them all):

```cpp-norun
mutable std::mutex m_mutex;            // mutable, so the const size() can lock it too
std::condition_variable m_ready;

// waiting side
std::unique_lock<std::mutex> lock{ m_mutex };
m_ready.wait(lock, [&] { return !m_items.empty() || m_closed; });
// here the lock is held again and the condition is true

// changing side
{ std::lock_guard<std::mutex> lock{ m_mutex }; m_items.push_back(std::move(item)); }
m_ready.notify_one();
```

`m_ready.wait(lock, predicate)` loops for you: it only returns when the predicate is true, so spurious wake-ups cannot make `pop` return early. `close` should use `notify_all`, so every waiting consumer wakes up and sees that the queue is closed.

unitTests:
#include <atomic>
#include <chrono>
#include <string>
#include <thread>
#include <vector>
TEST("in order, one thread") {
    WorkQueue<std::string> q; CHECK(q.push("a")); CHECK(q.push("b")); CHECK_EQ(q.size(), std::size_t{ 2 });
    CHECK_EQ(*q.pop(), std::string("a")); CHECK_EQ(*q.tryPop(), std::string("b")); CHECK(!q.tryPop().has_value());
}
TEST("closing") {
    WorkQueue<int> q; q.push(1); q.close(); CHECK(!q.push(2));
    CHECK_EQ(*q.pop(), 1); CHECK(!q.pop().has_value()); CHECK(!q.pop().has_value());
}
TEST("a waiting consumer wakes up") {
    WorkQueue<int> q; std::atomic<int> got{ -1 };
    std::thread consumer([&] { got = *q.pop(); });
    std::this_thread::sleep_for(std::chrono::milliseconds(20)); q.push(42); consumer.join(); CHECK_EQ(got.load(), 42);
    std::thread waiter([&] { got = q.pop().has_value() ? 1 : 0; });
    std::this_thread::sleep_for(std::chrono::milliseconds(20)); q.close(); waiter.join(); CHECK_EQ(got.load(), 0);
}
TEST("many producers and consumers") {
    WorkQueue<int> q; std::atomic<long long> sum{ 0 }; std::atomic<int> count{ 0 };
    std::vector<std::thread> consumers;
    for (int c = 0; c < 4; ++c) consumers.emplace_back([&] { while (auto v = q.pop()) { sum += *v; ++count; } });
    std::vector<std::thread> producers;
    for (int p = 0; p < 4; ++p) producers.emplace_back([&, p] { for (int i = 1; i <= 2500; ++i) q.push(p * 10000 + i); });
    for (auto& t : producers) t.join();
    q.close();
    for (auto& t : consumers) t.join();
    CHECK_EQ(count.load(), 10000); CHECK_EQ(sum.load(), 4LL * 3126250 + 2500LL * (0 + 10000 + 20000 + 30000)); CHECK_EQ(q.size(), std::size_t{ 0 });
}

